// frontend/src/components/Home.js

import React from 'react';
import { useAuth } from '../context/AuthContext'; // Import the useAuth hook

export default function Home() {
  // Get the user object and loading state from our AuthContext
  const { user, loading } = useAuth();

  // If the context is still loading the user data, show a loading message
  if (loading) {
    return <div>Loading...</div>;
  }

  // Once loaded, display the user's name
  // We use "user &&" as a safety check to ensure user is not null
  return (
    <div>
      <h1>Welcome, {user ? user.name : 'Guest'}!</h1>
      {/* You can display other user data here as well */}
      {user && <p>Your email is: {user.email}</p>}
    </div>
  );
}
